INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('0b3bdfa2-651c-543e-aaa3-ec7dc10a5ba4', '986e6b51-4731-5397-a26f-a20b4d8c84ae', '166d7108-7dc6-558e-a2d4-753be42ba6ac', 147, 147, 'ማለዳ ጮኽኹ ቃልኽንም ተስፋ አድርጌያለኹ'),
  ('757cf571-a4e8-58c7-afd4-4315e83927ab', '986e6b51-4731-5397-a26f-a20b4d8c84ae', '166d7108-7dc6-558e-a2d4-753be42ba6ac', 148, 148, 'ቃልኽን ዐስብ ዘንድ ዐይኖቼ ለመማለድ ቀደሙ'),
  ('b1ec9b65-2ee1-506d-ad12-33f81d5c5dae', '986e6b51-4731-5397-a26f-a20b4d8c84ae', '166d7108-7dc6-558e-a2d4-753be42ba6ac', 149, 149, 'አቤቱ እንደ ቸርነትኽ ድምፄን ስማ እንደ ፍርድኽ ሕያው አድርገኝ'),
  ('a693d034-27d2-538e-a614-4525c859c6db', '986e6b51-4731-5397-a26f-a20b4d8c84ae', '166d7108-7dc6-558e-a2d4-753be42ba6ac', 150, 150, 'በዐመፃ የሚያሳድዱኝ ቀረቡ ከሕግኽም ራቁ'),
  ('f24dbe1e-b20b-5b20-a345-7ca322235232', '986e6b51-4731-5397-a26f-a20b4d8c84ae', '166d7108-7dc6-558e-a2d4-753be42ba6ac', 151, 151, 'አቤቱ አንተ ቅርብ ነኽ መንገዶችኽም ዅሉ ቅኖች ናቸው'),
  ('b5a00652-5bb5-5d47-a14e-f751a8ee8c05', '986e6b51-4731-5397-a26f-a20b4d8c84ae', '166d7108-7dc6-558e-a2d4-753be42ba6ac', 152, 152, 'ከዘለዓለም እንደ መሠረትኸው ከቀድሞ ዠምሮ ከምስክርኽ የተነሣ ዐወቅኹ ሬስ'),
  ('43986210-9bf1-56e4-ab5a-a351ac69371c', '986e6b51-4731-5397-a26f-a20b4d8c84ae', '166d7108-7dc6-558e-a2d4-753be42ba6ac', 153, 153, 'ሕግኽን አልረሳኹምና ችግሬን ተመልከት አድነኝም'),
  ('00d252e2-485f-5b85-a544-52b205906ba6', '986e6b51-4731-5397-a26f-a20b4d8c84ae', '166d7108-7dc6-558e-a2d4-753be42ba6ac', 154, 154, 'ፍርዴን ፍረድ አድነኝም ስለ ቃልኽ ሕያው አድርገኝ'),
  ('b1e46ab4-becf-5be8-aab9-ddb0c844567b', '986e6b51-4731-5397-a26f-a20b4d8c84ae', '166d7108-7dc6-558e-a2d4-753be42ba6ac', 155, 155, 'መድኀኒት ከኃጥኣን ሩቅ ነው ሥርዐትኽን አልፈለጉምና'),
  ('2941900a-c738-5910-a9a6-16ebc2c15a9d', '986e6b51-4731-5397-a26f-a20b4d8c84ae', '166d7108-7dc6-558e-a2d4-753be42ba6ac', 156, 156, 'አቤቱ ቸርነትኽ እጅግ ብዙ ነው እንደ ፍርድኽ ሕያው አድርገኝ'),
  ('1256a17d-b9e1-500e-ad64-8bf921bba43a', '986e6b51-4731-5397-a26f-a20b4d8c84ae', '166d7108-7dc6-558e-a2d4-753be42ba6ac', 157, 157, 'ያሳደዱኝና ያስጨነቁኝ ብዙዎች ናቸው ከምስክር ግን ፈቀቅ አላልኹም'),
  ('b1544f5c-5824-5359-a227-29e3d1708aa7', '986e6b51-4731-5397-a26f-a20b4d8c84ae', '166d7108-7dc6-558e-a2d4-753be42ba6ac', 158, 158, 'ቃልኽን አልጠበቁምና ሰነፎችን አይቼ ዐዘንኹ'),
  ('12891572-33da-59cd-a83f-fd7bf157816f', '986e6b51-4731-5397-a26f-a20b4d8c84ae', '166d7108-7dc6-558e-a2d4-753be42ba6ac', 159, 159, 'ትእዛዝኽን እንደ ወደድኹ ተመልከት አቤቱ በምሕረትኽ ሕያው አድርገኝ'),
  ('8e28998c-c411-501c-a8a1-8487c5f747a8', '986e6b51-4731-5397-a26f-a20b4d8c84ae', '166d7108-7dc6-558e-a2d4-753be42ba6ac', 160, 160, 'የቃልኽ መዠመሪያ እውነት ነው የጽድቅኽንም ፍርድ ዅሉ ለዘለዓለም ነው ሳን'),
  ('709979bc-9f0c-5f14-a8c0-efac1f0e85c3', '986e6b51-4731-5397-a26f-a20b4d8c84ae', '166d7108-7dc6-558e-a2d4-753be42ba6ac', 161, 161, 'ገዢዎች በከንቱ አሳደዱኝ ከቃልኽ የተነሣ ግን ልቤ ደነገጠብኝ'),
  ('db5144f6-4065-5570-aa4d-0acd63d657ad', '986e6b51-4731-5397-a26f-a20b4d8c84ae', '166d7108-7dc6-558e-a2d4-753be42ba6ac', 162, 162, 'ብዙ ምርኮ እንዳገኘ በቃልኽ ደስ አለኝ'),
  ('e9212d35-ade7-520c-ad3b-3846f2687ab9', '986e6b51-4731-5397-a26f-a20b4d8c84ae', '166d7108-7dc6-558e-a2d4-753be42ba6ac', 163, 163, 'ዐመፃን ጠላኹ ተጸየፍኹም ሕግን ግን ወደድኹ'),
  ('14d8cf43-545b-5e09-a7b0-39592ce02081', '986e6b51-4731-5397-a26f-a20b4d8c84ae', '166d7108-7dc6-558e-a2d4-753be42ba6ac', 164, 164, 'ስለ ጽድቅኽ ፍርድ ሰባት ጊዜ በቀን አመሰግንኻለኹ'),
  ('19b5510b-658b-592b-af06-fd3d18534661', '986e6b51-4731-5397-a26f-a20b4d8c84ae', '166d7108-7dc6-558e-a2d4-753be42ba6ac', 165, 165, 'ሕግኽን ለሚወዱ ብዙ ሰላም ነው ዕንቅፋትም የለባቸውም'),
  ('a4c9813c-2d7f-55da-a887-83108dc37bd1', '986e6b51-4731-5397-a26f-a20b4d8c84ae', '166d7108-7dc6-558e-a2d4-753be42ba6ac', 166, 166, 'አቤቱ ማዳንኽን ተስፋ አደርግኹ ትእዛዛትኽንም ጠበቅኹ'),
  ('2bba2eb3-aec7-506a-a205-8b42746ed72f', '986e6b51-4731-5397-a26f-a20b4d8c84ae', '166d7108-7dc6-558e-a2d4-753be42ba6ac', 167, 167, 'ነፍሴ ምስክርኽን ጠበቀች እጅግም ወደደችው'),
  ('8fbc8369-7e4a-54b8-a751-cb947aa40c31', '986e6b51-4731-5397-a26f-a20b4d8c84ae', '166d7108-7dc6-558e-a2d4-753be42ba6ac', 168, 168, 'መንገዶቼ ዅሉ በፊትኽ ናቸውና ትእዛዝኽንና ምስክርኽን ጠበቅኹ ታው'),
  ('1e48b1ee-a741-5d2f-a805-229f9014edf2', '986e6b51-4731-5397-a26f-a20b4d8c84ae', '166d7108-7dc6-558e-a2d4-753be42ba6ac', 169, 169, 'አቤቱ ጸሎቴ ወደ ፊትኽ ትቅረብ እንደ ቃልኽም አስተዋይ አድርገኝ'),
  ('36d29c58-8cff-59de-ab9d-28afd59ba141', '986e6b51-4731-5397-a26f-a20b4d8c84ae', '166d7108-7dc6-558e-a2d4-753be42ba6ac', 170, 170, 'ልመናዬ ወደ ፊትኽ ትድረስ እንደ ቃልኽ አድነኝ'),
  ('505d5aa3-12b6-545a-a0f9-c89e426d60c4', '986e6b51-4731-5397-a26f-a20b4d8c84ae', '166d7108-7dc6-558e-a2d4-753be42ba6ac', 171, 171, 'ሥርዐትኽን አስተምረኸኛልና ከንፈሮቼ ምስጋናን አወጡ'),
  ('33f7c8e3-e417-56ab-a1e6-c3fa8107af56', '986e6b51-4731-5397-a26f-a20b4d8c84ae', '166d7108-7dc6-558e-a2d4-753be42ba6ac', 172, 172, 'ትእዛዛትኽ ዅሉ ጽድቅ ናቸውና አንደበቴ ቃልኽን ተናገረ'),
  ('8b3e7bf4-c4ab-5dda-aacf-292dddd70bb5', '986e6b51-4731-5397-a26f-a20b4d8c84ae', '166d7108-7dc6-558e-a2d4-753be42ba6ac', 173, 173, 'ትእዛዛትኽን መርጫለኹና እጅኽ የሚያድነኝ ይኹን'),
  ('43ba8a54-f007-5495-aba0-6c8e0314c7aa', '986e6b51-4731-5397-a26f-a20b4d8c84ae', '166d7108-7dc6-558e-a2d4-753be42ba6ac', 174, 174, 'አቤቱ ማዳንኽን ናፈቅኹ ሕግኽም ተድላዬ ነው'),
  ('6d092256-f9fa-5f4c-a95c-0ea77cd87032', '986e6b51-4731-5397-a26f-a20b4d8c84ae', '166d7108-7dc6-558e-a2d4-753be42ba6ac', 175, 175, 'ነፍሴ ትኑርልኝ ታመሰግንኽማለች ፍርድኽም ይርዳኝ'),
  ('b95db7e1-ed1e-583c-adfc-3c0e7ce3d767', '986e6b51-4731-5397-a26f-a20b4d8c84ae', '166d7108-7dc6-558e-a2d4-753be42ba6ac', 176, 176, 'እንደ ጠፉ በግ ተቅበዘበዝኹ ትእዛዛትኽን አልረሳኹምና ባሪያኽን ፈልገው'),
  ('8edea51a-90b0-5010-ae8b-5f5eefca5537', '37d436ff-bf00-5a8b-ab4f-3fe3c8612872', '7021f713-dc6e-5237-aada-2fc32c90b030', 1, 1, 'በተጨነቅኹ ጊዜ ወደ እግዚአብሔር ጮኽኹ ሰማኝም'),
  ('260c3031-aa3f-5614-ad1d-16d7d2524164', '37d436ff-bf00-5a8b-ab4f-3fe3c8612872', '7021f713-dc6e-5237-aada-2fc32c90b030', 2, 2, 'ከዐመፀኛ ከንፈር ከሸንጋይም አንደበት አቤቱ ነፍሴን አድናት'),
  ('9f3663cb-9f1a-51eb-aa99-97588420e6cf', '37d436ff-bf00-5a8b-ab4f-3fe3c8612872', '7021f713-dc6e-5237-aada-2fc32c90b030', 3, 3, 'ስለሽንገላ አንደበት ምንም ይሰጡኻል ምንስ ይጨምሩልኻል'),
  ('a435bfc5-690f-58ad-ab78-946d7bb06987', '37d436ff-bf00-5a8b-ab4f-3fe3c8612872', '7021f713-dc6e-5237-aada-2fc32c90b030', 4, 4, 'እንደ በረሓ ዕንጨት ፍም የኀያላን ፍላጻዎች የተሳሉ ናቸው'),
  ('d5e17935-82cc-5a28-aedc-7b2cd44da407', '37d436ff-bf00-5a8b-ab4f-3fe3c8612872', '7021f713-dc6e-5237-aada-2fc32c90b030', 5, 5, 'መኖሪያዬ የራቀ እኔ ወዮልኝ በቄዳር ድንኳኖች ዐደርኹ'),
  ('244f423b-87c7-5b36-a02d-192f528276fe', '37d436ff-bf00-5a8b-ab4f-3fe3c8612872', '7021f713-dc6e-5237-aada-2fc32c90b030', 6, 6, 'ሰላምን ከሚጠሉ ጋራ ነፍሴ ብዙ ጊዜ ኖረች'),
  ('04031e60-256a-5b14-a4c5-1d240d7dba29', '37d436ff-bf00-5a8b-ab4f-3fe3c8612872', '7021f713-dc6e-5237-aada-2fc32c90b030', 7, 7, 'እኔ ሰላማዊ ነኝ በተናገርዃቸው ጊዜ ግን በከንቱ ተሰለፉብኝ'),
  ('851c5b88-d335-5e58-a77e-da62fa3eff3b', 'c091614e-cf7c-52ed-a087-47d302591f5c', 'c949b111-426b-5e72-aa9a-2bda8d798354', 1, 1, 'ዐይኖቼ ወደ ተራራዎች አነሣኹ ረዳቴ ከወዴት ይምጣ'),
  ('13c9b05b-8196-5960-a687-7579ac4e7fbc', 'c091614e-cf7c-52ed-a087-47d302591f5c', 'c949b111-426b-5e72-aa9a-2bda8d798354', 2, 2, 'ረዳቴ ሰማይና ምድርን ከሠራ ከእግዚአብሔር ዘንድ ነው'),
  ('e1bedb01-154c-5359-a217-0a42fcca367e', 'c091614e-cf7c-52ed-a087-47d302591f5c', 'c949b111-426b-5e72-aa9a-2bda8d798354', 3, 3, 'እግርኽን ለመናወጥ አይሰጠውም የሚጠብቅኽም አይተኛም'),
  ('d6d5e4ad-ea77-58c0-a2a9-1c7538d12bca', 'c091614e-cf7c-52ed-a087-47d302591f5c', 'c949b111-426b-5e72-aa9a-2bda8d798354', 4, 4, 'እንሆ እስራኤልን የሚጠብቅ አይተኛም አያንቀላፋምም'),
  ('c2de99bd-f7d7-5a60-a902-03ebeb4dc386', 'c091614e-cf7c-52ed-a087-47d302591f5c', 'c949b111-426b-5e72-aa9a-2bda8d798354', 5, 5, 'እግዚአብሔር ይጠብቅኻል እግዚአብሔርም በቀኝ እጅኽ በኩል ይጋርድኻል'),
  ('6b9ef14d-7d46-51fa-a23a-7694a904acf2', 'c091614e-cf7c-52ed-a087-47d302591f5c', 'c949b111-426b-5e72-aa9a-2bda8d798354', 6, 6, 'ፀሓይ በቀን አያቃጥልኽም ጨረቃም በሌሊት'),
  ('e5ec0f8f-0202-5a8e-a7e9-6594bbc54947', 'c091614e-cf7c-52ed-a087-47d302591f5c', 'c949b111-426b-5e72-aa9a-2bda8d798354', 7, 7, 'እግዚአብሔር ከክፉ ዅሉ ይጠብቅኻል ነፍስኽንም ይጠብቃታል'),
  ('a22d78c0-bf11-5e34-ad16-ebadf6980f82', 'c091614e-cf7c-52ed-a087-47d302591f5c', 'c949b111-426b-5e72-aa9a-2bda8d798354', 8, 8, 'ከዛሬ ዠምሮ እስከ ዘለዓለም እግዚአብሔር መውጣትኽና መግባትኽን ይጠብቃል'),
  ('423c881a-df90-5462-a79d-e93afbe68fab', '81f5f7d3-562b-5289-a6e7-652559df4e36', 'c008d4ec-9187-5c0f-a467-30e7ff1b10df', 1, 1, 'ወደእግዚአብሔር ቤት እንኺድ ባሉኝ ጊዜ ደስ አለኝ'),
  ('0123ce34-ad68-5f4b-ab34-b241e95640be', '81f5f7d3-562b-5289-a6e7-652559df4e36', 'c008d4ec-9187-5c0f-a467-30e7ff1b10df', 2, 2, 'ኢየሩሳሌም ሆይ እግሮቻችን በአደባባይሽ ቆሙ'),
