  ('9a992cc2-1120-54a1-a2d7-8680cdf541a8', '81f5f7d3-562b-5289-a6e7-652559df4e36', 'c008d4ec-9187-5c0f-a467-30e7ff1b10df', 5, 5, 'ዙፋኖች በዚያ ለፍርድ ተቀምጠዋልና የዳዊት ቤት ዙፋኖች'),
  ('e76ee5ba-5cb6-582d-ad8b-5687bac89ee2', '81f5f7d3-562b-5289-a6e7-652559df4e36', 'c008d4ec-9187-5c0f-a467-30e7ff1b10df', 6, 6, 'ለኢየሩሳሌም ሰላምን ለምኑ አንተንም ለሚወዱ ልማት ይኹን'),
