  ('bdf8b980-e36a-5122-a7f2-e5665864adde', '04082635-0a7b-5c2d-a96b-037f97e034ba', '8c236e13-489f-56ec-a0e8-f234046948e1', 1, 1, 'በሰማይ የምትኖር ሆይ ዐይኖቼን ወዳንተ አነሣኹ'),
  ('c349bdba-641c-56dd-a3e4-30b379df695f', '04082635-0a7b-5c2d-a96b-037f97e034ba', '8c236e13-489f-56ec-a0e8-f234046948e1', 2, 2, 'እንሆ የባሪያዎች ዐይኖች ወደጌታቸው እጅ እንደ ኾኑ የባሪያዪቱም ዐይን ወደእመቤቷ እጅ እንደ ኾ ነ እንዲሁ እስኪምረን ድረስ ዐይናችን ወደ አምላካችን ወደ እግዚአብሔር ነው'),
  ('f0ebb093-2378-5c87-af79-d88904c7e96d', '04082635-0a7b-5c2d-a96b-037f97e034ba', '8c236e13-489f-56ec-a0e8-f234046948e1', 3, 3, 'ማረን አቤቱ ማረን ንቀትን እጅግ ጠግበናልና'),
  ('e1dfd49b-ae09-502b-ae53-e808f73d1394', '04082635-0a7b-5c2d-a96b-037f97e034ba', '8c236e13-489f-56ec-a0e8-f234046948e1', 4, 4, 'የባለጠጋዎች ስድብና የትዕቢተኛዎችን ንቀት ነፍሳችን እጅግ ጠገበች'),
  ('eb28d7ff-e5f0-5911-a065-ce331f4f668c', '8a24f57a-edcb-5c5e-acd4-e1f2afe72996', 'ce950f0d-3f6c-5bab-adce-29e29cf18a70', 1, 1, 'እግዚአብሔር ከእኛ ጋራ ባይኾን እስራኤል እንዲህ ይበል፦'),
