  ('be8c640c-3a7b-5cc3-a7bb-4b9aca7e4eba', '8a24f57a-edcb-5c5e-acd4-e1f2afe72996', 'ce950f0d-3f6c-5bab-adce-29e29cf18a70', 3, 3, 'ቍጣቸው በላያችን በነደደ ጊዜ በዚያን ጊዜ ሕያዋን ሳለን በዋጡን ነበር'),
  ('ba185ba5-f1a5-5e1f-af3f-7b63832e2a1f', '8a24f57a-edcb-5c5e-acd4-e1f2afe72996', 'ce950f0d-3f6c-5bab-adce-29e29cf18a70', 4, 4, 'በዚያን ጊዜ ውሃ ባሰጠመን ነበር በነፍሳችንም ላይ ፈሳሽ ባለፈ ነበር'),
  ('14371b50-2a07-51fd-ab2c-3a35cf7fde7b', '8a24f57a-edcb-5c5e-acd4-e1f2afe72996', 'ce950f0d-3f6c-5bab-adce-29e29cf18a70', 5, 5, 'በዚያን ጊዜ የጐርፍ ውሃ በነፍሳችን ላይ ባለፈ ነበር'),
