  ('69ab2166-a633-56d5-a7b1-7ee0267f76ad', '8a24f57a-edcb-5c5e-acd4-e1f2afe72996', 'ce950f0d-3f6c-5bab-adce-29e29cf18a70', 8, 8, 'ረድኤታችን ሰማይንና ምድርን በሠራ በእግዚአብሔር ስም ነው'),
