  ('97d14cbd-4949-5b52-af7d-a5c5318dc911', '3deb6614-92ba-5c2d-a7be-e52dcc0f02c5', 'afa4ca21-0edf-521c-a215-f65218893c16', 2, 2, 'ተራራዎች በኢየሩሳሌም ዙሪያ እንደ ኾኑ ከዛሬ ዠምሮ ለዘለዓለም እግዚአብሔር በሕዝቡ ዙሪያ ነው'),
  ('81840daa-f4ea-56aa-a899-1d8712d765f6', '3deb6614-92ba-5c2d-a7be-e52dcc0f02c5', 'afa4ca21-0edf-521c-a215-f65218893c16', 3, 3, 'ጻድቃን እጃቸውን ወደ ክፋት እንዳይዘረጉ የኃጥኣን በትር በጻድቃን ዕጣ ላይ አይኖርም'),
  ('610dfe11-10cf-5482-a7a7-f043bf002c60', '3deb6614-92ba-5c2d-a7be-e52dcc0f02c5', 'afa4ca21-0edf-521c-a215-f65218893c16', 4, 4, 'አቤቱ ለቸሮች ልባቸውም ለቀና መልካምን አድርግ'),
  ('05d54fea-d37d-5338-a8b7-5cb259f41832', '3deb6614-92ba-5c2d-a7be-e52dcc0f02c5', 'afa4ca21-0edf-521c-a215-f65218893c16', 5, 5, 'ወደ ጠማማነት የሚመለሱትን ግን ዐመፃን ከሚሠሩት ጋራ እግዚአብሔር ይወስዳቸዋል ሰላም በእስራኤል ላይ ይኹን'),
  ('4b220116-b111-5376-a2f4-3392d000ff16', '32a56a2b-e5d1-54dd-af6b-6b86b0e11d12', '886e3742-5927-5c90-a0f9-33eea449b588', 1, 1, 'እግዚአብሔር የጽዮንን ምርኮ በመለሰ ጊዜ እጅግ ደስተኛዎች ኾን፟'),
  ('be4f264c-bbd9-591d-a6f0-49d643511fdc', '32a56a2b-e5d1-54dd-af6b-6b86b0e11d12', '886e3742-5927-5c90-a0f9-33eea449b588', 2, 2, 'በዚያን ጊዜ አፋችን ደስታን አንደበታችንም ሐሴትን ሞላ በዚያን ጊዜ በአሕዛብ ዘንድ እግዚአብሔር ታላቅ ነገርን አደረገላቸው ተባለ'),
