  ('7b52faab-4f26-59f4-aa9a-955037273c92', '32a56a2b-e5d1-54dd-af6b-6b86b0e11d12', '886e3742-5927-5c90-a0f9-33eea449b588', 4, 4, 'አቤቱ በደቡብ እንዳሉ ፈሳሾች ምርኳችንን መልስ'),
  ('b1a478e8-d97e-589e-a6a9-9663648fe041', '32a56a2b-e5d1-54dd-af6b-6b86b0e11d12', '886e3742-5927-5c90-a0f9-33eea449b588', 5, 5, 'በልቅሶ የሚዘሩ በደስታ ይለቅማሉ'),
  ('8996696d-e21c-5f8b-a787-19af5ad162d8', '32a56a2b-e5d1-54dd-af6b-6b86b0e11d12', '886e3742-5927-5c90-a0f9-33eea449b588', 6, 6, 'በኼዱ ጊዜ ዘራቸውን ተሸክመው እያለቀሱ ተሰማሩ በተመለሱ ጊዜ ግን ነዷቸውን ተሸክመው ደስ እያላ ቸው ይመጣሉ'),
  ('fea0b71f-0f1f-5a50-a436-d445a56e08d7', 'f894bddd-aecf-55a1-a10d-808ec292ef6b', '5d09ece7-a584-527c-a06e-273bd207c709', 1, 1, 'እግዚአብሔር ቤትን ካልሠራ ሠራተኛዎች በከንቱ ይደክማሉ እግዚአብሔር ከተማን ካልጠበቀ ጠባቂ በከ ንቱ ይተጋል'),
  ('2261d090-5b1c-5295-a4f2-38e05fa9c029', 'f894bddd-aecf-55a1-a10d-808ec292ef6b', '5d09ece7-a584-527c-a06e-273bd207c709', 2, 2, 'በማለዳ መገሥገሣችኹም ከንቱ ነው ለወዳጆቹ እንቅልፍን በሰጠ ጊዜ እናንተ የመከራን እንጀራ የምት በሉ ከተቀመጣችኹበት ተነሡ'),
  ('d89f51a0-70ca-5c7b-acbf-67de51cd4d2b', 'f894bddd-aecf-55a1-a10d-808ec292ef6b', '5d09ece7-a584-527c-a06e-273bd207c709', 3, 3, 'እንሆ ልጆች የእግዚአብሔር ስጦታ ናቸው የሆድም ፍሬ የርሱ ዋጋ ነው'),
  ('76dd1906-08c3-5f2d-a50e-d38784d68ff1', 'f894bddd-aecf-55a1-a10d-808ec292ef6b', '5d09ece7-a584-527c-a06e-273bd207c709', 4, 4, 'በኀያል እጅ እንዳሉ ፍላጻዎች የጐልማስነት ልጆች እንዲሁ ናቸው'),
