  ('fed665f0-1918-5eab-ae07-f8679abc85ef', '21800123-a3d5-50bf-ada8-b8f06504b8c9', 'babb3ab7-7b11-5554-a749-8c47aa248781', 16, 16, 'ካህናቷንም ደኅንነትን አለብሳቸዋለኹ ቅዱሳኖቿም እጅግ ደስ ይላቸዋል'),
  ('b702de1a-432e-5007-aca0-8c198be0adef', '21800123-a3d5-50bf-ada8-b8f06504b8c9', 'babb3ab7-7b11-5554-a749-8c47aa248781', 17, 17, 'በዚያ ለዳዊት ቀንድን አበቅላለኹ ለቀባኹትም ሰው መብራትን አዘጋጃለኹ'),
  ('850cc0fc-b75c-5612-ab79-87c4bce9384b', '21800123-a3d5-50bf-ada8-b8f06504b8c9', 'babb3ab7-7b11-5554-a749-8c47aa248781', 18, 18, 'ጠላቶችንም ዕፍረትን አለብሳቸዋለኹ በርሱ ግን ቅድስናዬ ያብባል'),
  ('d1664167-715d-553a-a8a9-007d8b62837d', '8374323c-89d2-5619-a5b5-efd48faff325', 'b0560020-d048-5e60-a5b5-3dd3e650723f', 1, 1, 'ወንድሞች በኅብረት ቢቀመጡ እንሆ መልካም ነው እንሆም ያማረ ነው'),
  ('8dec2024-a85c-5fa6-a368-df77c12a09f5', '8374323c-89d2-5619-a5b5-efd48faff325', 'b0560020-d048-5e60-a5b5-3dd3e650723f', 2, 2, 'ከራስ እስከ ጢም እንደሚፈስ፟ እስከአሮን ጢም በልብሱ መደረቢያ እንደሚወርድ ሽቱ ነው'),
  ('91c70945-38c8-54bd-a359-51bc3a5f4044', '8374323c-89d2-5619-a5b5-efd48faff325', 'b0560020-d048-5e60-a5b5-3dd3e650723f', 3, 3, 'በጽዮን ተራራዎች እንደሚወርድ እንደ አርሞንዔም ጠል ነው በዚያ እግዚአብሔር በረከቱን ሕይወትንም እስከ ዘለዓለም አዟ፟ልና'),
  ('ba84e283-cdc5-5f28-ad17-2101ed02f4f4', '51eb050c-6480-52f4-af32-9e05c4b30d03', 'e3374b8a-a2f8-5c16-a9ce-d5dc83724d81', 1, 1, 'እንሆ እግዚአብሔርን ባርኩ በአምላካችን ቤት አደባባዮች የምትቆሙ እናንተ የእግዚአብሔር ባሪያዎች ዅላችኹ'),
  ('ee11648f-ddc7-536a-a5de-6f39449dd149', '51eb050c-6480-52f4-af32-9e05c4b30d03', 'e3374b8a-a2f8-5c16-a9ce-d5dc83724d81', 2, 2, 'በሌሊት በቤተ መቅደስ ውስጥ እጆቻችኹን አንሡ እግዚአብሔርንም ባርኩ'),
  ('c88505ec-fb14-5e50-aa53-172e2f9844de', '51eb050c-6480-52f4-af32-9e05c4b30d03', 'e3374b8a-a2f8-5c16-a9ce-d5dc83724d81', 3, 3, 'ሰማይንና ምድርን የሠራ እግዚአብሔር ከጽዮን ይባርክኽ'),
  ('44418e1d-edca-5c11-af66-c9be5ebc7473', '62421367-11db-56bb-ae6a-8dfb6d81088d', 'bec23fe2-b44a-5b95-a566-8925aece24a5', 1, 1, 'ሃሌ ሉያ የእግዚአብሔርን ስም አመስግኑ እናንተ የእግዚአብሔር ባሪያዎች ሆይ አመስግኑት'),
  ('c8e070fd-86be-5ed1-a6d0-a1e2d9d2476d', '62421367-11db-56bb-ae6a-8dfb6d81088d', 'bec23fe2-b44a-5b95-a566-8925aece24a5', 2, 2, 'በእግዚአብሔር ቤት ውስጥ በአምላካችን ቤት አደባባይ የምትቆሙ'),
  ('301a065e-2d4d-551c-ab6b-203a88c862bb', '62421367-11db-56bb-ae6a-8dfb6d81088d', 'bec23fe2-b44a-5b95-a566-8925aece24a5', 3, 3, 'እግዚአብሔር ቸር ነውና እግዚአብሔርን አመስግኑ ለስሙ ዘምሩ መልካም ነውና'),
