  ('c8756492-38cb-52aa-a2d8-f7daa9c914a7', '62421367-11db-56bb-ae6a-8dfb6d81088d', 'bec23fe2-b44a-5b95-a566-8925aece24a5', 5, 5, 'እግዚአብሔር ታላቅ እንደ ኾነ ጌታችንም ከአማልክት ዅሉ እንዲበልጥ ዐውቄያለኹና'),
  ('d95cf1c8-cace-5f2f-a5c4-2500bb0fcbaf', '62421367-11db-56bb-ae6a-8dfb6d81088d', 'bec23fe2-b44a-5b95-a566-8925aece24a5', 6, 6, 'በሰማይና በምድር በባሕርና በጥልቆች ዅሉ እግዚአብሔር የወደደውን ዅሉ አደረገ'),
  ('1def85ec-5d41-59b4-a2a7-960bab6ab67a', '62421367-11db-56bb-ae6a-8dfb6d81088d', 'bec23fe2-b44a-5b95-a566-8925aece24a5', 7, 7, 'ከምድር ዳር ደመናትን ያወጣል በዝናብ ጊዜ መብረቅን አደረገ ነፋሳትንም ከመዛግብቱ ያወጣል'),
  ('a33c8f8b-28f4-56b1-a97a-383963afd626', '62421367-11db-56bb-ae6a-8dfb6d81088d', 'bec23fe2-b44a-5b95-a566-8925aece24a5', 8, 8, 'የግብጽን በኵር ልጆች ከሰው ዠምሮ እስከ እንስሳ ድረስ መታ'),
  ('6bf86987-6779-526a-aa27-6f781fdf06a1', '62421367-11db-56bb-ae6a-8dfb6d81088d', 'bec23fe2-b44a-5b95-a566-8925aece24a5', 9, 9, 'ግብጽ ሆይ በመካከልሽ በፈርዖንና በባሪያዎቹ ዅሉ ላይ ተኣምራትንና ድንቅን ሰደደ'),
  ('2d394a96-db0c-5694-a6cf-cf90b6c2f341', '62421367-11db-56bb-ae6a-8dfb6d81088d', 'bec23fe2-b44a-5b95-a566-8925aece24a5', 10, 10, 'ብዙ አሕዛብን መታ ብርቱዎችንም ነገሥታት ገደለ'),
