  ('e2ddb37c-8ede-5aa0-a2f1-e2e37e9ba95a', '62421367-11db-56bb-ae6a-8dfb6d81088d', 'bec23fe2-b44a-5b95-a566-8925aece24a5', 14, 14, 'እግዚአብሔር ለሕዝቡ ይፈርዳልና ባሪያዎቹንም ይረዳልና'),
