  ('f0547572-8e7c-5e14-a029-517490fb7fbc', '62421367-11db-56bb-ae6a-8dfb6d81088d', 'bec23fe2-b44a-5b95-a566-8925aece24a5', 18, 18, 'የሚሠሯቸው ዅሉ የሚታመኑባቸውም ዅሉ እንደ እነርሱ ይኹን'),
