  ('ed0c4b1e-4d3b-598a-a1fe-65f00465cf02', '8f1a823e-20f2-5303-a418-115d0c6c4ee1', '80f86e99-fe05-59a3-a83e-699f19fe2c0b', 1, 1, 'እግዚአብሔርን አመስግኑ ቸር ነውና ምሕረቱ ለዘለዓለም ነውና'),
