  ('876a1b3a-53ca-5fdb-af79-55b32b53b666', '8f1a823e-20f2-5303-a418-115d0c6c4ee1', '80f86e99-fe05-59a3-a83e-699f19fe2c0b', 4, 4, 'ርሱ ብቻውን ታላቅ ተኣምራትን ያደረገ ምሕረቱ ለዘለዓለም ነውና'),
