  ('d477fe1c-2424-5baa-a240-fbe48c11491e', '9548404d-5ceb-5d6b-aabc-9453b67249a7', '8e3e4ad8-8a82-5328-ad3e-7888cf61cf74', 5, 5, 'ኢየሩሳሌም ሆይ ብረሳሽ ቀኜ ትርሳኝ'),
  ('63435369-af2b-5786-a628-cd09d104644b', '9548404d-5ceb-5d6b-aabc-9453b67249a7', '8e3e4ad8-8a82-5328-ad3e-7888cf61cf74', 6, 6, 'ባላስብሽ ምላሴ በጕረሮዬ ይጣበቅ ከደስታዬ ዅሉ በላይ ኢየሩሳሌምን ባልወድ፟'),
  ('0c55d791-ecc2-5556-ae90-631c19f77fca', '9548404d-5ceb-5d6b-aabc-9453b67249a7', '8e3e4ad8-8a82-5328-ad3e-7888cf61cf74', 7, 7, 'አቤቱ በኢየሩሳሌም ቀን የኤዶምን ልጆች ዐስብ እስከ መሠረቷ ድረስ አፍርሱ አፍርሱ ያሏትን'),
  ('e8946504-2368-5420-abbb-c64f5fff7643', '9548404d-5ceb-5d6b-aabc-9453b67249a7', '8e3e4ad8-8a82-5328-ad3e-7888cf61cf74', 8, 8, 'አንቺ ወራዳ የባቢሎን ልጅ ሆይ ስለ ተበቀልሽን የሚበቀልሽ የተመሰገነ ነው'),
  ('0d1e9008-2ebf-577d-a702-3cfc68141ffa', '9548404d-5ceb-5d6b-aabc-9453b67249a7', '8e3e4ad8-8a82-5328-ad3e-7888cf61cf74', 9, 9, 'ሕፃናትሽን ይዞ በአለት ላይ የሚፈጠፍጣቸው የተመሰገነ ነው'),
  ('a801e2aa-b7f9-5901-ad34-610fc54aa382', '51415808-6bf4-5f41-a6e3-5b5704014459', '1732d861-24e0-50eb-abb2-70567515b4a4', 1, 1, 'አቤቱ በፍጹም ልቤ አመሰግንኻለኹ የአፌን ነገር ሰምተኸኛልና በመላእክት ፊት እዘምርልኻለኹ'),
