  ('991d3f78-2af9-5527-ab47-bf6a9652c656', '51415808-6bf4-5f41-a6e3-5b5704014459', '1732d861-24e0-50eb-abb2-70567515b4a4', 3, 3, 'በጠራኹኽ ቀን በፍጥነት አድምጠኝ ነፍሴን በኀይልኽ በብዙ አጸናኻት'),
  ('e08c7369-148b-582a-a80b-bd63879fba47', '51415808-6bf4-5f41-a6e3-5b5704014459', '1732d861-24e0-50eb-abb2-70567515b4a4', 4, 4, 'አቤቱ የምድር ነገሥታት ዅሉ ያመሰግኑኻል የአፍኽን ቃል ዅሉ ሰምተዋልና'),
  ('00ac181a-5918-5f22-a6c0-eddf99e6bb5f', '51415808-6bf4-5f41-a6e3-5b5704014459', '1732d861-24e0-50eb-abb2-70567515b4a4', 5, 5, 'በእግዚአብሔርም መንገድ ይዘምራሉ የእግዚአብሔር ክብር ታላቅ ነውና'),
  ('93164504-1fa9-5f73-a278-350424c8e5fb', '51415808-6bf4-5f41-a6e3-5b5704014459', '1732d861-24e0-50eb-abb2-70567515b4a4', 6, 6, 'እግዚአብሔር ከፍ ያለ ነውና ወደ ችግረኛዎችም ይመለከታልና ትዕቢተኛዎችንም ከሩቅ ያውቃል'),
  ('bcc302c3-2cb9-5598-a2f1-d32aea15a0f1', '51415808-6bf4-5f41-a6e3-5b5704014459', '1732d861-24e0-50eb-abb2-70567515b4a4', 7, 7, 'በመከራ መካከል እንኳ ብኼድ አንተ ሕያው ታደርገኛለኽ በጠላቶቼ ቍጣ ላይ እጆቼን ትዘረጋለኽ ቀኝ ኽም ታድነኛለች'),
  ('d085533d-e857-58da-a62b-ae0e8d6d51c0', '51415808-6bf4-5f41-a6e3-5b5704014459', '1732d861-24e0-50eb-abb2-70567515b4a4', 8, 8, 'እግዚአብሔር ብድራትን ይመልስልኛል አቤቱ ምሕረትኽ ለዘለዓለም ነው አቤቱ የእጅኽን ሥራ ቸል አት በል'),
  ('76ed0442-88f0-5434-ac73-43ec38c6e5f9', 'ae0da993-62d3-5abb-a70c-564186200440', '7f006548-afcc-5342-a777-a7649145d93d', 1, 1, 'አቤቱ መረመርኸኝ ዐወቅኸኝም'),
  ('ae5e80b1-51bb-58c9-add5-79ce3cdb796c', 'ae0da993-62d3-5abb-a70c-564186200440', '7f006548-afcc-5342-a777-a7649145d93d', 2, 2, 'አንተ መቀመጤንና መነሣቴን ዐወቅኽ ዐሳቤን ዅሉ ከሩቅ አስተዋልኽ'),
  ('9252d4d4-2d64-510a-a39f-76f8ee212833', 'ae0da993-62d3-5abb-a70c-564186200440', '7f006548-afcc-5342-a777-a7649145d93d', 3, 3, 'ፍለጋዬንና ዕረፍቴን አንተ መረመርኽ መንገዶቼን ዅሉ ቀድመኽ ዐወቅኽ'),
  ('de344aca-4313-53ce-a486-f61d2b45b356', 'ae0da993-62d3-5abb-a70c-564186200440', '7f006548-afcc-5342-a777-a7649145d93d', 4, 4, 'የዐመፃ ቃል በአንደበቴ እንደሌለ'),
  ('d8574eea-909a-5b36-a70f-14abb7e32523', 'ae0da993-62d3-5abb-a70c-564186200440', '7f006548-afcc-5342-a777-a7649145d93d', 5, 5, 'አቤቱ አንተ እንሆ የቀድሞውንና የዃላውን ዐወቅኽ አንተ ፈጠርኸኝ እጅኽንም በላዬ አደረግኽ'),
  ('190e1fa6-7ae5-5bb3-a351-8be4eda18cea', 'ae0da993-62d3-5abb-a70c-564186200440', '7f006548-afcc-5342-a777-a7649145d93d', 6, 6, 'ዕውቀትኽ ከእኔ ይልቅ ተደነቀች በረታች ወደ ርሷም ለመድረስ አልችልም'),
  ('2810311c-c068-5ece-a91d-7c90faee0f79', 'ae0da993-62d3-5abb-a70c-564186200440', '7f006548-afcc-5342-a777-a7649145d93d', 7, 7, 'ከመንፈስኽ ወዴት እኼዳለኹ ከፊትኽስ ወዴት እሸሻለኹ'),
  ('d67c0791-d581-5c3b-a16d-247b0692e003', 'ae0da993-62d3-5abb-a70c-564186200440', '7f006548-afcc-5342-a777-a7649145d93d', 8, 8, 'ወደ ሰማይ ብወጣ አንተ በዚያ አለኽ ወደ ሲኦልም ብወርድ በዚያ አለኽ'),
  ('20b7b52f-5466-5d20-af35-aa8a58e16975', 'ae0da993-62d3-5abb-a70c-564186200440', '7f006548-afcc-5342-a777-a7649145d93d', 9, 9, 'እንደ ንስር የንጋትን ክንፍ ብወስድ እስከባሕር መጨረሻም ብበር፟'),
  ('938ebd83-be35-52f4-a2de-ff093c3e00dd', 'ae0da993-62d3-5abb-a70c-564186200440', '7f006548-afcc-5342-a777-a7649145d93d', 10, 10, 'በዚያ እጅኽ ትመራኛለች ቀኝኽም ትይዘኛለች'),
  ('fd8748db-f4f6-5e05-ad06-0781bf2f5504', 'ae0da993-62d3-5abb-a70c-564186200440', '7f006548-afcc-5342-a777-a7649145d93d', 11, 11, 'በእውኑ ጨለማ ትሸፍነኛለች ብል ሌሊት በዙሪያዬ ብርሃን ትኾናለች'),
  ('0aaf3c74-cb93-502e-a390-0187d8ff7958', 'ae0da993-62d3-5abb-a70c-564186200440', '7f006548-afcc-5342-a777-a7649145d93d', 12, 12, 'ጨለማ ባንተ ዘንድ አይጨልምምና ሌሊትም እንደ ቀን ታበራለችና እንደ ጨለማዋ እንዲሁ ብርሃኗ ነ ው'),
  ('8fcead24-3752-5225-a220-5603e294717e', 'ae0da993-62d3-5abb-a70c-564186200440', '7f006548-afcc-5342-a777-a7649145d93d', 13, 13, 'አቤቱ አንተ ኵላሊቴን ፈጥረኻልና በእናቴም ሆድ ሰውረኸኛል'),
  ('3fd16a21-28e8-5ebd-a8ce-16873ab9f92e', 'ae0da993-62d3-5abb-a70c-564186200440', '7f006548-afcc-5342-a777-a7649145d93d', 14, 14, 'ግሩምና ድንቅ ኾኜ ተፈጥሬያለኹና አመሰግንኻለኹ ሥራኽ ድንቅ ነው ነፍሴም እጅግ ታውቀዋለች'),
  ('bbe61bd4-730c-52ce-a66b-691ead3973d6', 'ae0da993-62d3-5abb-a70c-564186200440', '7f006548-afcc-5342-a777-a7649145d93d', 15, 15, 'እኔ በስውር በተሠራኹ ጊዜ አካሌም በምድር ታች በተሠራ ጊዜ ዐጥንቶቼ ከአንተ አልተሰወሩም'),
  ('5b957e71-1bdf-518c-a3a8-324affb2e51b', 'ae0da993-62d3-5abb-a70c-564186200440', '7f006548-afcc-5342-a777-a7649145d93d', 16, 16, 'ያልተሠራ አካሌን ዐይኖችኽ አዩኝ የተፈጠሩ ቀኖቼ ዅሉ አንድ ስንኳ ሳይኖር በመጽሐፍኽ ተጻፉ'),
  ('f0fa7bc9-e930-5d3b-a912-c78858ae53f1', 'ae0da993-62d3-5abb-a70c-564186200440', '7f006548-afcc-5342-a777-a7649145d93d', 17, 17, 'አቤቱ ዐሳቦችኽ በእኔ ዘንድ እንደ ምን እጅግ የተከበሩ ናቸው! ቍጥራቸውም እንደ ምን በዛ!'),
  ('028aa065-ba9a-5725-af0c-a3f909ebb831', 'ae0da993-62d3-5abb-a70c-564186200440', '7f006548-afcc-5342-a777-a7649145d93d', 18, 18, 'ብቈጥራቸው ከአሸዋ ይልቅ ይበዛሉ ተነሣኹም እኔም ገና ከአንተ ጋራ ነኝ'),
  ('28c01317-4ad5-56f6-aebb-079d43c66e58', 'ae0da993-62d3-5abb-a70c-564186200440', '7f006548-afcc-5342-a777-a7649145d93d', 19, 19, 'አቤቱ አንተ ኀጢአተኛዎችን የምትገድል ከኾንኽስ የደም ሰዎች ሆይ ከእኔ ፈቀቅ በሉ'),
  ('273312ed-7032-5c60-a8c3-a31edfd53e6e', 'ae0da993-62d3-5abb-a70c-564186200440', '7f006548-afcc-5342-a777-a7649145d93d', 20, 20, 'በክፋት ይናገሩብኻልና ጠላቶችኽም በከንቱ ያምፁብኻል'),
  ('ae9e9cad-3805-5ceb-ad64-2947fd66c09a', 'ae0da993-62d3-5abb-a70c-564186200440', '7f006548-afcc-5342-a777-a7649145d93d', 21, 21, 'አቤቱ የሚጠሉኽን እኔ የጠላኹ አይደለኹምን ስለ ጠላቶችኽም አልተሰቀቅኹምን'),
  ('df17cf94-70a6-5f68-a62c-2d0ba2f4d53a', 'ae0da993-62d3-5abb-a70c-564186200440', '7f006548-afcc-5342-a777-a7649145d93d', 22, 22, 'ፍጹም ጥል ጠላዃቸው ጠላቶችም ኾኑኝ'),
  ('94f1bbd4-34da-585a-a755-af6ff85c1ea0', 'ae0da993-62d3-5abb-a70c-564186200440', '7f006548-afcc-5342-a777-a7649145d93d', 23, 23, 'አቤቱ መርምረኝ ልቤንም ዕወቅ ፍተነኝ መንገዴንም ዕወቅ'),
  ('e52f12ec-a532-5106-a19b-41d26c027bb4', 'ae0da993-62d3-5abb-a70c-564186200440', '7f006548-afcc-5342-a777-a7649145d93d', 24, 24, 'በደልንም በእኔ ውስጥ ብታገኝ እይ የዘለዓለምንም መንገድ ምራኝ'),
  ('3f826f2d-2b77-538b-ac9f-72f986d38274', 'a07716ec-87c5-5402-aaa3-fb7a11eadbd2', 'ce5308ef-3909-57ac-a3b9-5b8316c6af74', 1, 1, 'አቤቱ ከክፉ ሰው አድነኝ በልባቸውም ክፉ ካሰቡ ከዐመፀኛዎች ሰዎች ጠብቀኝ'),
  ('80c22601-0243-571d-a3e2-27035fe0de40', 'a07716ec-87c5-5402-aaa3-fb7a11eadbd2', 'ce5308ef-3909-57ac-a3b9-5b8316c6af74', 2, 2, 'ቀኑን ዅሉ ለሰልፍ ይከማቻሉ'),
  ('d7772884-1fa9-5a8d-a167-c444b3c700cd', 'a07716ec-87c5-5402-aaa3-fb7a11eadbd2', 'ce5308ef-3909-57ac-a3b9-5b8316c6af74', 3, 3, 'ምላሳቸውን እንደ እባብ ሳሉ ከከንፈራቸው በታች የእፍኝት መርዝ ነው'),
  ('32b187d6-0881-596c-a984-88628162b1aa', 'a07716ec-87c5-5402-aaa3-fb7a11eadbd2', 'ce5308ef-3909-57ac-a3b9-5b8316c6af74', 4, 4, 'አቤቱ ከኀጢአተኛዎች እጅ ጠብቀኝ ርምጃዬንም ሊያሰናክሉ ከመከሩ ከዐመፀኛዎች አድነኝ'),
  ('9211e128-7883-5dfd-ab73-7510e5ee78bd', 'a07716ec-87c5-5402-aaa3-fb7a11eadbd2', 'ce5308ef-3909-57ac-a3b9-5b8316c6af74', 5, 5, 'ትዕቢተኛዎች ወጥመድን ሰወሩብኝ ለእግሮቼም የወጥመድ ገመድን ዘረጉ በመንገድ ዕንቅፋትን አኖሩ'),
  ('26022f76-8d25-51dd-af1c-07acbc8bc917', 'a07716ec-87c5-5402-aaa3-fb7a11eadbd2', 'ce5308ef-3909-57ac-a3b9-5b8316c6af74', 6, 6, 'እግዚአብሔርንም፦አንተ አምላኬ ነኽ የልመናዬን ቃል አቤቱ አድምጥ አልኹት'),
  ('84ae44ed-01c9-5a76-af0e-15200d6e1544', 'a07716ec-87c5-5402-aaa3-fb7a11eadbd2', 'ce5308ef-3909-57ac-a3b9-5b8316c6af74', 7, 7, 'አቤቱ ጌታዬ የመድኀኒቴ ጕልበት በሰልፍ ቀን ራሴን ሸፈንኽ'),
  ('6f3e1cd3-04b0-50e0-af42-ed1ccad9dc25', 'a07716ec-87c5-5402-aaa3-fb7a11eadbd2', 'ce5308ef-3909-57ac-a3b9-5b8316c6af74', 8, 8, 'አቤቱ ከምኞቴ የተነሣ ለኀጢአተኛዎች አትስጠኝ በላዬ ተማከሩ እንዳይጓደዱ አትተወኝ'),
  ('240ff24b-9ad1-5752-a32f-bd8795f9a465', 'a07716ec-87c5-5402-aaa3-fb7a11eadbd2', 'ce5308ef-3909-57ac-a3b9-5b8316c6af74', 9, 9, 'የሚከቡ፟ኝን ራስ የከንፈራቸው ክፋት ይክደናቸው'),
  ('4a0ed8fb-e964-548b-a632-7332128d22d0', 'a07716ec-87c5-5402-aaa3-fb7a11eadbd2', 'ce5308ef-3909-57ac-a3b9-5b8316c6af74', 10, 10, 'የእሳት ፍም በላያቸው ይውደቅ እንዳይነሡም ወደ እሳትና ወደ ማዕበል ይጣሉ'),
  ('5361cbe0-0844-5c69-a210-0985ee5a1808', 'a07716ec-87c5-5402-aaa3-fb7a11eadbd2', 'ce5308ef-3909-57ac-a3b9-5b8316c6af74', 11, 11, 'ተናጋሪ ሰው በምድር ውስጥ አይጸናም ዐመፀኛን ሰው ክፋት ለጥፋት ይፈልገዋል'),
  ('0c2f16f3-f46c-5df4-a58e-043929810835', 'a07716ec-87c5-5402-aaa3-fb7a11eadbd2', 'ce5308ef-3909-57ac-a3b9-5b8316c6af74', 12, 12, 'እግዚአብሔር ለድኻ ዳኝነትን ለችግረኛም ፍርድን እንዲያደርግ ዐወቅኹ'),
  ('a7925d05-1dfc-562a-ab69-0baab1633052', 'a07716ec-87c5-5402-aaa3-fb7a11eadbd2', 'ce5308ef-3909-57ac-a3b9-5b8316c6af74', 13, 13, 'ጻድቃንም በእውነት ስምኽን ያመሰግናሉ ቀኖችም በፊትኽ ይኖራሉ'),
  ('9770ce60-a5ed-5d70-af8e-51012db85513', 'ae6f3d44-deab-55ec-a8be-198b9c30a3de', '3a8baf0f-502d-53fe-a3f3-c28cc37baed5', 1, 1, 'አቤቱ ወዳንተ ጮኽኹ ስማኝ ወዳንተ ስጮኽም የልመናዬን ቃል አድምጥ'),
  ('cf6aa1e0-4ff5-5f32-a517-a65451906552', 'ae6f3d44-deab-55ec-a8be-198b9c30a3de', '3a8baf0f-502d-53fe-a3f3-c28cc37baed5', 2, 2, 'ጸሎቴን በፊትኽ እንደ ዕጣን ተቀበልልኝ እጅ መንሣቴም እንደ ሠርክ መሥዋዕት ትኹን'),
  ('e7e4e9d6-76f7-55c1-a534-193bc67c2997', 'ae6f3d44-deab-55ec-a8be-198b9c30a3de', '3a8baf0f-502d-53fe-a3f3-c28cc37baed5', 3, 3, 'አቤቱ ለአፌ ጠባቂ አኑር የከንፈሮቼንም መዝጊያ ጠብቅ'),
  ('175b6ae1-869c-51fc-a499-94ca8a22762c', 'ae6f3d44-deab-55ec-a8be-198b9c30a3de', '3a8baf0f-502d-53fe-a3f3-c28cc37baed5', 4, 4, 'ልቤን ወደ ክፉ ነገር አትመልሰው ዐመፃን ከሚያደርጉ ሰዎች ጋራ ለኀጢአት ምክንያት እንዳልሰጥ ከ ምርጦቻቸውም ጋራ አልተባበር'),
  ('39e1dc64-3d24-59dc-a7f1-4e210a8451ff', 'ae6f3d44-deab-55ec-a8be-198b9c30a3de', '3a8baf0f-502d-53fe-a3f3-c28cc37baed5', 5, 5, 'ጻድቅ በምሕረት ይገሥጸኝ ይዝለፈኝም የኀጢአተኛ ዘይት ግን ራሴን አይቅባ ጸሎቴ ገና በክፋታቸው ላይ ነውና'),
  ('c1bc0b97-310a-57ef-a9cd-33269747a0e7', 'ae6f3d44-deab-55ec-a8be-198b9c30a3de', '3a8baf0f-502d-53fe-a3f3-c28cc37baed5', 6, 6, 'ኀያላናቸው በአለት አጠገብ ተጣሉ ጣፋጭ ናትና ቃሌን ይሰማሉ'),
  ('f8e0a360-2d96-501d-a4d0-53b8f99bfc56', 'ae6f3d44-deab-55ec-a8be-198b9c30a3de', '3a8baf0f-502d-53fe-a3f3-c28cc37baed5', 7, 7, 'በምድር ላይ እንደ ተሰነጠቀ እንደ መሬት ጓል እንዲሁ ዐጥንቶቻችን በሲኦል ተበተኑ'),
  ('004a5f7e-5b7d-5cfa-aed2-d26b0623cf5f', 'ae6f3d44-deab-55ec-a8be-198b9c30a3de', '3a8baf0f-502d-53fe-a3f3-c28cc37baed5', 8, 8, 'አቤቱ ጌታ ዐይኖቼ ወዳንተ ናቸውና ባንተ ታመንኹ ነፍሴን አታውጣት'),
  ('c5336fe6-3bba-5dd4-abcc-4db360365a5e', 'ae6f3d44-deab-55ec-a8be-198b9c30a3de', '3a8baf0f-502d-53fe-a3f3-c28cc37baed5', 9, 9, 'ከሰወሩብኝ ወጥመድ ዐመፅንም ከሚያደርጉ ሰዎች ዕንቅፋት ጠብቀኝ'),
  ('63e4848e-f306-5cb2-a7a7-07bf13f166ec', 'ae6f3d44-deab-55ec-a8be-198b9c30a3de', '3a8baf0f-502d-53fe-a3f3-c28cc37baed5', 10, 10, 'እኔ ብቻዬን እስካልፍ ድረስ ኀጢአተኛዎች በወጥመዳቸው ይውደቁ'),
  ('94728e8a-156d-5cfe-a335-f7c177f861b5', '1e10e9b2-796f-50e0-a2dd-4f3558eb327c', 'ba72665a-78ed-52ad-a69b-7f85bcd7bb73', 1, 1, 'በቃሌ ወደ እግዚአብሔር ጮኽኹ በቃሌ ወደ እግዚአብሔር ለመንኹ'),
  ('c6783791-d0cf-5d02-a48d-7f5ab38a263f', '1e10e9b2-796f-50e0-a2dd-4f3558eb327c', 'ba72665a-78ed-52ad-a69b-7f85bcd7bb73', 2, 2, 'ልመናዬን በፊቱ አፈሳ፟ለኹ መከራዬንም በፊቴ እናገራለኹ'),
  ('8e37a088-ce29-51ac-a42f-3264b0b6c553', '1e10e9b2-796f-50e0-a2dd-4f3558eb327c', 'ba72665a-78ed-52ad-a69b-7f85bcd7bb73', 3, 3, 'ነፍሴ በውስጤ ባለቀች ጊዜ መንገዴን ዐወቅኹ በምኼድባት በዚያች መንገድ ወጥመድን ሰወሩብኝ'),
  ('4c50cd9e-29db-5716-a2a3-9ea6efeab5b6', '1e10e9b2-796f-50e0-a2dd-4f3558eb327c', 'ba72665a-78ed-52ad-a69b-7f85bcd7bb73', 4, 4, 'ወደ ቀኝ ተመለከትኹ አየኹም የሚያውቀኝም ዐጣኹ መሸሸጊያም የለኝም ስለ ነፍሴም የሚመራመር የለም'),
  ('ec913f75-56bb-5b3b-a90d-5fb22bd722d9', '1e10e9b2-796f-50e0-a2dd-4f3558eb327c', 'ba72665a-78ed-52ad-a69b-7f85bcd7bb73', 5, 5, 'አቤቱ ወዳንተ ጮኽኹ፦አንተ ተስፋዬ ነኽ በሕያዋንም ምድር አንተ ዕድል ፈንታዬ ነኽ አልኹ'),
  ('bf8b21cb-3ba1-5859-a0b6-467fa2120084', '1e10e9b2-796f-50e0-a2dd-4f3558eb327c', 'ba72665a-78ed-52ad-a69b-7f85bcd7bb73', 6, 6, 'እጅግ ተቸግሬያለኹና ወደ ልመናዬ አድምጥ በርትተውብኛልና ከሚያሳድዱኝ አድነኝ'),
  ('8dd52a2f-d88e-53d3-a28f-c3cf02ef58d5', '1e10e9b2-796f-50e0-a2dd-4f3558eb327c', 'ba72665a-78ed-52ad-a69b-7f85bcd7bb73', 7, 7, 'አቤቱ ስምኽን አመሰግን ዘንድ ነፍሴን ከወህኒ አውጣት ዋጋዬን እስክትሰጠኝ ድረስ ጻድቃን እኔን ይጠብቃሉ'),
  ('06879f72-7527-5549-abcd-e0d8000e73f6', '93d1d9f9-813e-5b87-a42e-cd5eb160233c', '6cebe62c-bc43-5dbb-aeed-46fd42523cce', 1, 1, 'አቤቱ ጸሎቴን ስማ በእውነትኽ ልመናዬን አድምጥ በጽድቅኽም መልስልኝ')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('4684372f-4d47-507d-a546-f72fc67a2c53', '93d1d9f9-813e-5b87-a42e-cd5eb160233c', '6cebe62c-bc43-5dbb-aeed-46fd42523cce', 2, 2, 'ሕያው ዅሉ በፊትኽ ጻድቅ አይደለምና ከባሪያኽ ጋራ ወደ ፍርድ አትግባ'),
  ('992f1059-2c33-520d-ac42-537669a52698', '93d1d9f9-813e-5b87-a42e-cd5eb160233c', '6cebe62c-bc43-5dbb-aeed-46fd42523cce', 3, 3, 'ጠላትኽ ነፍሴን አሳዷ፟ታል ሕይወቴንም በምድር ውስጥ አጐስቍሏታል ቀድሞ እንደ ሞተ ሰው በጨለማ አኑሮኛል'),
  ('8216f54d-13a2-5919-acf8-e12f4ea9041a', '93d1d9f9-813e-5b87-a42e-cd5eb160233c', '6cebe62c-bc43-5dbb-aeed-46fd42523cce', 4, 4, 'ነፍሴ በውስጤ አለቀችብኝ ልቤም በውስጤ ደነገጠብኝ'),
  ('f382e298-e13a-594a-a6e9-47ebeaa0ec2d', '93d1d9f9-813e-5b87-a42e-cd5eb160233c', '6cebe62c-bc43-5dbb-aeed-46fd42523cce', 5, 5, 'የቀድሞውን ዘመን ዐሰብኹ ሥራኽንም ዅሉ አሰላሰልኹ የእጅኽንም ሥራ ተመለከትኹ'),
  ('072f931a-00e7-5d6a-a96f-39cc719e0d1f', '93d1d9f9-813e-5b87-a42e-cd5eb160233c', '6cebe62c-bc43-5dbb-aeed-46fd42523cce', 6, 6, 'እጆቼን ወዳንተ ዘረጋኹ ነፍሴም እንደ ምድረ በዳ አንተን ተጠማች'),
  ('cb6bc676-f42d-5cd0-a356-8b29bfc5fe05', '93d1d9f9-813e-5b87-a42e-cd5eb160233c', '6cebe62c-bc43-5dbb-aeed-46fd42523cce', 7, 7, 'አቤቱ ፈጥነኽ ስማኝ ነፍሴ አልቃለች ፊትኽን ከእኔ አትመልስ ወደ ጕድጓድም እንደሚወርዱ አልኹን'),
  ('dc3d4a7a-7d54-5af0-aa75-bb7dd8070982', '93d1d9f9-813e-5b87-a42e-cd5eb160233c', '6cebe62c-bc43-5dbb-aeed-46fd42523cce', 8, 8, 'አንተን ታምኛለኹና በማለዳ ምሕረትኽን አሰማኝ አቤቱ ነፍሴን ወዳንተ አንሥቻለኹና የምኼድበትን መ ንገድ አስታውቀኝ'),
  ('02a618f0-d988-5107-a956-07805029f76b', '93d1d9f9-813e-5b87-a42e-cd5eb160233c', '6cebe62c-bc43-5dbb-aeed-46fd42523cce', 9, 9, 'አቤቱ ወዳንተ ተማፅኛለኹና ከጠላቶቼ አድነኝ'),
  ('d3bfe7f3-3f36-576b-a441-d6ea53ae5869', '93d1d9f9-813e-5b87-a42e-cd5eb160233c', '6cebe62c-bc43-5dbb-aeed-46fd42523cce', 10, 10, 'አንተ አምላኬ ነኽና ፈቃድኽን ለማድረግ አስተምረኝ ቅዱስ መንፈስኽም በጽድቅ ምድር ይምራኝ'),
  ('c29f4b85-ee9f-542e-ae81-44eeb47b8fce', '93d1d9f9-813e-5b87-a42e-cd5eb160233c', '6cebe62c-bc43-5dbb-aeed-46fd42523cce', 11, 11, 'አቤቱ ስለ ስምኽ ሕያው አድርገኝ በጽድቅኽም ነፍሴን ከመከራዋ አውጣት'),
  ('e5b585af-97ef-5bc5-a38f-d24140dc4c09', '93d1d9f9-813e-5b87-a42e-cd5eb160233c', '6cebe62c-bc43-5dbb-aeed-46fd42523cce', 12, 12, 'በምሕረትኽ ጠላቶቼን ደምስሳቸው እኔ ባሪያኽ ነኝና ነፍሴን የሚያስጨንቋትን ዅሉ አጥፋቸው'),
  ('4be113f3-0095-51a6-ac48-a5ff78f03d92', '03e6f93b-c581-570b-a30d-abfede21aead', 'ccc43553-0104-5067-ac4f-09bfc00d6d2f', 1, 1, 'እግዚአብሔር አምላኬ ይባረክ ለእጆቼ ሰልፍን ለጣቶቼም ዘመቻን የሚያስተምር'),
  ('d75bd76f-88b5-54ce-aa05-9cad4da4b83a', '03e6f93b-c581-570b-a30d-abfede21aead', 'ccc43553-0104-5067-ac4f-09bfc00d6d2f', 2, 2, 'መሓሪዬና መሸሸጊያዬ መጠጊያዬና መድኀኒቴ ረዳቴና መታመኛዬም ሕዝቤንም ከእኔ በታች የሚያስገዛልኝ'),
  ('deb8712d-69e0-53ec-ae5e-c170149f3d65', '03e6f93b-c581-570b-a30d-abfede21aead', 'ccc43553-0104-5067-ac4f-09bfc00d6d2f', 3, 3, 'አቤቱ ርሱን ታውቀው ዘንድ ሰው ምንድር ነው ታስብለት ዘንድ የሰው ልጅ ምንድር ነው'),
  ('9598005b-cd64-5e41-a8aa-f82c5f06ea3d', '03e6f93b-c581-570b-a30d-abfede21aead', 'ccc43553-0104-5067-ac4f-09bfc00d6d2f', 4, 4, 'ሰው ከንቱን ነገር ይመስላል ዘመኑ እንደ ጥላ ያልፋል'),
  ('888a76e7-dffe-54a2-ab90-d3980ec7378c', '03e6f93b-c581-570b-a30d-abfede21aead', 'ccc43553-0104-5067-ac4f-09bfc00d6d2f', 5, 5, 'አቤቱ ሰማዮችኽን ዝቅ ዝቅ አድርጋቸው ውረድም ተራራዎችን ዳስሳቸው ይጢሱም'),
  ('deab2d8e-425f-5a57-a96b-a4ff221f0a5e', '03e6f93b-c581-570b-a30d-abfede21aead', 'ccc43553-0104-5067-ac4f-09bfc00d6d2f', 6, 6, 'መብረቆችኽን ብልጭ አድርጋቸው በትናቸውም ፍላጻዎችኽን ላካቸው አስደንግጣቸውም 7-8 እጅኽን ከአርያም ላክ አድነኝም ከብዙ ውሃዎች አፋቸውም ምናምንን ከሚናገር ቀኛቸው የሐሰት ቀኝ ከኾነ ከባዕድ ልጆች እጅ አስጥለኝ'),
  ('b6f0fbe1-b4fa-5b38-a779-757ac2c4715e', '03e6f93b-c581-570b-a30d-abfede21aead', 'ccc43553-0104-5067-ac4f-09bfc00d6d2f', 7, 9, 'አቤቱ ዐዲስ ቅኔ እቀኝልኻለኹ ዐሥር አውታር ባለው በገና እዘምርልኻለኹ'),
  ('5ea6ca8a-a8c4-5284-a9af-0ff02eb45a7e', '03e6f93b-c581-570b-a30d-abfede21aead', 'ccc43553-0104-5067-ac4f-09bfc00d6d2f', 8, 10, 'ለነገሥታት መድኀኒትን የሚሰጥ ባሪያውን ዳዊትን ከክፉ ሰይፍ የሚያድነው ርሱ ነው'),
  ('1b66592d-9774-5f6a-a08e-e0efb9e2374f', '03e6f93b-c581-570b-a30d-abfede21aead', 'ccc43553-0104-5067-ac4f-09bfc00d6d2f', 9, 11, 'አድነኝ አፋቸውም ምናምንን ከሚናገር ቀኛቸውም የሐሰት ቀኝ ከኾነ ከባዕድ ልጆች እጅ አስጥለኝ'),
  ('24fb49ef-9820-5ba1-ac13-925bf0ba861c', '03e6f93b-c581-570b-a30d-abfede21aead', 'ccc43553-0104-5067-ac4f-09bfc00d6d2f', 10, 12, 'ልጆቻቸው በጕልማሳነታቸው እንደ ዐዲስ አትክልት የኾኑ ሴቶች ልጆቻቸውም እንደ ዕልፍኝ ያማሩና ያጌጡ'),
  ('477ffa8d-7122-59f7-a72f-a5010bbb4d1e', '03e6f93b-c581-570b-a30d-abfede21aead', 'ccc43553-0104-5067-ac4f-09bfc00d6d2f', 11, 13, 'ዕቃ ቤቶቻቸውም የተሞሉ በየዐይነቱ ዕቃ የሚሰጡ በጎቻቸውም ብዙ የሚወልዱ በማሰማሪያቸውም የሚበ ዙ'),
  ('d01a3ae4-b6a0-5cec-ace7-03f8d7e6bbe4', '03e6f93b-c581-570b-a30d-abfede21aead', 'ccc43553-0104-5067-ac4f-09bfc00d6d2f', 12, 14, 'ላሞቻቸውም የሚሰቡ ቅጥራቸውም መፍረሻና መውጫ የሌለው በአደባባዮቻቸውም ዋይታ የሌለ'),
  ('e3a7e42a-b7d3-5561-a600-c2e9b7a87c99', '03e6f93b-c581-570b-a30d-abfede21aead', 'ccc43553-0104-5067-ac4f-09bfc00d6d2f', 13, 15, 'እንደዚህ የሚኾን ሕዝብ የተመሰገነ ነው እግዚአብሔር አምላኩ የኾነ ሕዝብ ምስጉን ነው'),
