  ('3837c094-9731-5614-aee0-29bc5385ab2e', '761d9464-accd-5cea-a24b-87463b4663e5', '6396bfe5-0a8a-5ef4-ae43-69955e8a74b9', 3, 3, 'ልባቸውን የቈሰሉትን ይፈውሳል ሕማማቸውንም ይጠግናል'),
  ('1231f70c-f053-566e-ae50-095e3ff4e092', '761d9464-accd-5cea-a24b-87463b4663e5', '6396bfe5-0a8a-5ef4-ae43-69955e8a74b9', 4, 4, 'የከዋክብትንም ብዛት ይቈጥራል ዅሉንም በየስማቸው ይጠራቸዋል'),
  ('a67df696-f38e-5a57-aad0-b3312e2d3799', '761d9464-accd-5cea-a24b-87463b4663e5', '6396bfe5-0a8a-5ef4-ae43-69955e8a74b9', 5, 5, 'ጌታችን ታላቅ ነው ኀይሉም ታላቅ ነው ለጥበቡም ቍጥር የለውም'),
